'use strict';
// Coche: BMW M3 Touring 24H Shell Helix (2026)
// - Motor 3.0L S58 Twin-Turbo de 6 cilindros en línea con 530 CV y 650 Nm de par.
// - Preparación especial para las 24 Horas de Nürburgring con kit aerodinámico ensanchado.
// - Transmisión M Steptronic de 8 velocidades con Drivelogic y tracción trasera de carreras.
// - Sonido bronco y característico del 6 en línea biturbo bávaro con petardeos M Performance.
(() => {

const ATLAS_B64 = "data:image/png;base64,";
const BODY_V = "";
const BODY_I = "";
const GLASS_V = "";
const GLASS_I = "";
const WHEEL_V = "";
const WHEEL_I = "";


WGSL["mat_bmw_m3_touring_2026"] = `// Material BMW M3 Touring 24H
#include mesh_vert
@group(3) @binding(0) var tAtlas: texture_2d<f32>;

fn surf(in: V2F, ff: bool) -> Surface {
  var s = surfDefault(normalize(in.nrm));
  if (!ff) { s.normal = -s.normal; }

  let id = matId(in.mat);
  let uv = in.uv;
  let tx = textureSample(tAtlas, sLin, uv);

  if (id == 14u) {
    // Carrocería Shell Helix Livery (Amarillo / Rojo / Blanco oficial)
    s.albedo = tx.rgb;
    s.metal = 0.12;
    s.rough = 0.16;
    s.coat = 0.95;
  } else if (id == 33u) {
    // Llantas M Forged negro satinado
    s.albedo = tx.rgb;
    s.metal = 0.85;
    s.rough = 0.22;
    s.coat = 0.35;
  } else if (id == 20u) {
    // Pinzas M Sport rojas
    s.albedo = vec3f(0.95, 0.05, 0.05);
    s.metal = 0.40;
    s.rough = 0.20;
    s.coat = 0.80;
  } else if (id == 45u) {
    // DRLs amarillos / verde flúor estilo BMW M4 GT3
    s.albedo = tx.rgb * 1.5;
    s.emissive = 1.3;
    s.rough = 0.05;
  } else if (id == 38u || id == 80u) {
    // Fibra de carbono GT4 (splitter, faldones, alerón)
    s.albedo = tx.rgb;
    s.metal = 0.08;
    s.rough = 0.30;
    s.coat = 0.60;
  } else {
    s.albedo = tx.rgb;
    s.metal = 0.15;
    s.rough = 0.35;
  }

  return s;
}
`;

function loadAtlas() {
  const W = 2048, H = 2048;
  const tex = mkTex(W, H, 'rgba8unorm-srgb', TU.RT | TU.TB | TU.CD, { mipLevelCount: 7 });
  const initData = new Uint8Array(W * H * 4);
  initData.fill(30);
  G.dev.queue.writeTexture({ texture: tex }, initData, { bytesPerRow: W * 4 }, [W, H]);

  if (typeof Image !== 'undefined') {
    const img = new Image();
    img.src = ATLAS_B64;
    img.onload = () => {
      if (typeof createImageBitmap !== 'undefined') {
        createImageBitmap(img).then(bmp => {
          G.dev.queue.copyExternalImageToTexture({ source: bmp }, { texture: tex }, [W, H]);
          if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
        }).catch(() => {
          const cvs = document.createElement('canvas');
          cvs.width = W; cvs.height = H;
          const ctx2d = cvs.getContext('2d');
          ctx2d.drawImage(img, 0, 0);
          const id = ctx2d.getImageData(0, 0, W, H);
          G.dev.queue.writeTexture({ texture: tex }, id.data, { bytesPerRow: W * 4 }, [W, H]);
          if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
        });
      } else {
        const cvs = document.createElement('canvas');
        cvs.width = W; cvs.height = H;
        const ctx2d = cvs.getContext('2d');
        ctx2d.drawImage(img, 0, 0);
        const id = ctx2d.getImageData(0, 0, W, H);
        G.dev.queue.writeTexture({ texture: tex }, id.data, { bytesPerRow: W * 4 }, [W, H]);
        if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
      }
    };
  }
  return tex;
}

const CAR = {
  id: 'bmw-m3-touring-2026',
  name: 'BMW M3 Touring 24H',
  subtitle: '2026 24H Nürburgring Spec · 3.0L Twin-Turbo I6 S58 · RWD',
  specs: '1560 kg · 530 CV · 8-vel M Steptronic · RWD · Shell Helix Aero',
  accent: '#ffcc00',
  physics: {
    m: 1560, Izz: 2150, L: 2.899, a: 1.48, b: 1.42, tw: 1.72, h: 0.42, R: 0.350,
    mu: 1.68, B: 11.0, C: 1.50, driveF: 0.0,
    gears: [3.10, 2.25, 1.72, 1.38, 1.15, 0.98, 0.84, 0.72], final: 3.15, rev: 3.2, eff: 0.96,
    cdA: 0.72, crr: 0.010, brakeF: 0.62, halfW: 1.05, front: 2.50, rear: 2.45,
    clA: 0.85, aeroSplitF: 0.40,
    torqueBase: 420, torquePeak: 290, torqueDrop: 170, torquePeakStart: 0.40, torquePeakSpan: 5.0, torqueDropRpm: 7.2,
    shiftUpRpm: 7200, shiftDownRpm: 5200, revLimitRpm: 7500, maxRpm: 7800, idleRpm: 1100,
  },
  hud: { maxKmh: 325, maxRpm: 8.0, redlineRpm: 7.2 },
  wheelbase: 2.899, trackF: 1.723, trackR: 1.720, wheelR: 0.350,
  hubs: [
    [1.586, 0.426, -0.862],
    [1.586, 0.426, 0.860],
    [-1.314, 0.431, -0.860],
    [-1.314, 0.431, 0.860]
  ],
  slotBody: 0, slotWheel: [0, 0, 0, 0],
  tris: 0, _t: m4(), _t2: m4(), _t3: m4(), set: null, glass: null, atlasBG: null, fam: null,
  _z4: new Float32Array(4),
  inp: new Float64Array(2),

  build() {
    const fam = CAR.fam = mkFamily('car_bmw_m3_touring_2026', { src: 'mat_bmw_m3_touring_2026', noCube: true });
    CAR.slotBody = objSlot();
    for (let i = 0; i < 4; i++) CAR.slotWheel[i] = objSlot();

    const set = CAR.set = new MeshSet(fam);
    const mb = new MeshBuilder(1 << 19);
    const w = new MeshBuilder(1 << 16);

    const bV = b64ToF32(BODY_V), bI = b64ToU32(BODY_I);
    const wV = b64ToF32(WHEEL_V), wI = b64ToU32(WHEEL_I);

    const nbV = bV.length / 9;
    for (let i = 0; i < nbV; i++) {
      mb.mat(bV[i*9 + 8]);
      mb.v(bV[i*9], bV[i*9+1], bV[i*9+2], bV[i*9+3], bV[i*9+4], bV[i*9+5], bV[i*9+6], bV[i*9+7]);
    }
    for (let i = 0; i < bI.length; i += 3) mb.tri(bI[i], bI[i+1], bI[i+2]);

    const nwV = wV.length / 9;
    for (let i = 0; i < nwV; i++) {
      w.mat(wV[i*9 + 8]);
      w.v(wV[i*9], wV[i*9+1], wV[i*9+2], wV[i*9+3], wV[i*9+4], wV[i*9+5], wV[i*9+6], wV[i*9+7]);
    }
    for (let i = 0; i < wI.length; i += 3) w.tri(wI[i], wI[i+1], wI[i+2]);

    CAR.tris = mb.ni / 3;
    set.add(mb.upload(), CAR.slotBody, 3);

    const wm = w.upload();
    CAR.tris += 4 * w.ni / 3;
    for (let i = 0; i < 4; i++) set.add(wm, CAR.slotWheel[i], 3);

    const glass = CAR.glass = new GlassSet();
    const gl = new MeshBuilder(1 << 15);
    const gV = b64ToF32(GLASS_V), gI = b64ToU32(GLASS_I);
    const ngV = gV.length / 9;
    for (let i = 0; i < ngV; i++) {
      gl.mat(gV[i*9 + 8]);
      gl.v(gV[i*9], gV[i*9+1], gV[i*9+2], gV[i*9+3], gV[i*9+4], gV[i*9+5], gV[i*9+6], gV[i*9+7]);
    }
    for (let i = 0; i < gI.length; i += 3) gl.tri(gI[i], gI[i+1], gI[i+2]);
    CAR.tris += gl.ni / 3;
    glass.add_(gl.upload(), CAR.slotBody);
    R.transparents.push(glass);

    const tex = loadAtlas();
    R.drawables.push({
      draw(pass, ctx) {
        if (ctx.kind === KIND.SHADOW && ctx.cascade === 3) return;
        if (!CAR.atlasBG) {
          if (!fam.bgl3) return;
          CAR.atlasBG = G.dev.createBindGroup({ layout: fam.bgl3, entries: [{ binding: 0, resource: tex.createView() }] });
        }
        pass.setBindGroup(3, CAR.atlasBG);
        set.draw(pass, ctx);
      },
    });

    m4ident(CAR._t);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    console.log('[BMW M3 Touring 24H] Inicializado con éxito. Triángulos:', CAR.tris);
  },

  place(body, spin, susp) {
    const steer = CAR.inp[0];
    const t = CAR._t2;
    objPrev(CAR.slotBody).set(objModel(CAR.slotBody));
    objModel(CAR.slotBody).set(body);
    for (let i = 0; i < 4; i++) {
      const sl = CAR.slotWheel[i], h = CAR.hubs[i], left = (i & 1) === 0;
      objPrev(sl).set(objModel(sl));
      const a = -(i < 2 ? steer : 0) + (left ? PI : 0), c = Math.cos(a), sn = Math.sin(a);
      const g = left ? spin[i] : -spin[i], cg = Math.cos(g), sg = Math.sin(g);
      t[0] = c * cg; t[1] = sg; t[2] = -sn * cg; t[3] = 0;
      t[4] = -c * sg; t[5] = cg; t[6] = sn * sg; t[7] = 0;
      t[8] = sn; t[9] = 0; t[10] = c; t[11] = 0;
      t[12] = h[0]; t[13] = h[1] + susp[i]; t[14] = h[2]; t[15] = 1;
      m4mul(objModel(sl), body, t);
    }
  },
};

CARS.register(CAR);
})();
